// Окно отчёта: последние 7 дней до момента запуска.
// При запуске по cron (понедельник 09:00) это ровно прошедшая неделя.
const REPO = 'Fufuraziy/ITMOv2';
const DAY = 24 * 60 * 60 * 1000;
const iso = d => d.toISOString().replace(/\.\d{3}Z$/, 'Z');
const date = d => d.toISOString().slice(0, 10);

const until = new Date();
const since = new Date(until.getTime() - 7 * DAY);

return [{ json: {
  repo: REPO,
  since: iso(since),
  until: iso(until),
  week_start: date(since),
  week_end: date(until),
}}];

// Группируем данные четырёх запросов к GitHub по типу и по автору.
const w = $('Week range').first().json;
const items = name => $(name).first().json.items || [];

const issuesOpened = items('GitHub: issues opened');
const issuesClosed = items('GitHub: issues closed');
const prsOpened = items('GitHub: PRs opened');
const prsMerged = items('GitHub: PRs merged');

const TYPES = ['bug', 'feature', 'task', 'needs-triage', 'unlabeled'];
function typeOf(issue) {
  const names = (issue.labels || []).map(l => String(l.name || l).toLowerCase());
  for (const t of ['bug', 'feature', 'task']) if (names.includes(t)) return t;
  if (names.includes('needs-triage') || names.includes('unknown')) return 'needs-triage';
  return 'unlabeled';
}

// По типу: сколько Issues каждого типа открыто и закрыто за неделю
const by_type = {};
for (const t of TYPES) by_type[t] = { opened: 0, closed: 0 };
for (const i of issuesOpened) by_type[typeOf(i)].opened++;
for (const i of issuesClosed) by_type[typeOf(i)].closed++;

// По автору: активность каждого пользователя за неделю
const by_author = {};
const bump = (login, key) => {
  login = login || 'unknown';
  by_author[login] = by_author[login] || { issues_opened: 0, issues_closed: 0, prs_opened: 0, prs_merged: 0 };
  by_author[login][key]++;
};
for (const i of issuesOpened) bump(i.user && i.user.login, 'issues_opened');
for (const i of issuesClosed) bump(i.user && i.user.login, 'issues_closed');
for (const p of prsOpened) bump(p.user && p.user.login, 'prs_opened');
for (const p of prsMerged) bump(p.user && p.user.login, 'prs_merged');

const totals = {
  issues_opened: issuesOpened.length,
  issues_closed: issuesClosed.length,
  prs_opened: prsOpened.length,
  prs_merged: prsMerged.length,
};

return [{ json: {
  repo: w.repo, week_start: w.week_start, week_end: w.week_end, since: w.since, until: w.until,
  totals, by_type, by_author,
  issues: issuesOpened.map(i => ({ number: i.number, title: i.title, type: typeOf(i), author: i.user && i.user.login, url: i.html_url })),
}}];

// Ищем в Data Table предыдущую неделю и считаем Δ.
const cur = $('Group stats').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.week_start);
const prev = rows
  .filter(r => r.week_start < cur.week_start)
  .sort((a, b) => (a.week_start < b.week_start ? 1 : -1))[0] || null;

const parse = s => { try { return typeof s === 'string' ? JSON.parse(s) : (s || {}); } catch (e) { return {}; } };
const METRICS = ['issues_opened', 'issues_closed', 'prs_opened', 'prs_merged'];

let delta = null;
if (prev) {
  const prevType = parse(prev.by_type);
  delta = { totals: {}, by_type: {} };
  for (const m of METRICS) delta.totals[m] = (cur.totals[m] || 0) - (Number(prev[m]) || 0);
  for (const t of Object.keys(cur.by_type)) {
    const p = prevType[t] || { opened: 0, closed: 0 };
    delta.by_type[t] = {
      opened: cur.by_type[t].opened - (p.opened || 0),
      closed: cur.by_type[t].closed - (p.closed || 0),
    };
  }
}

return [{ json: {
  ...cur,
  prev: prev ? {
    week_start: prev.week_start, week_end: prev.week_end,
    totals: Object.fromEntries(METRICS.map(m => [m, Number(prev[m]) || 0])),
    by_type: parse(prev.by_type),
  } : null,
  delta,
  history_rows: rows.length,
}}];

