// Собираем HTML-письмо: итоги с Δ, таблицы по типу и по автору, AI-комментарий.
const s = $('Compute delta').first().json;
const ai = String($input.first().json.text || '').trim();

const esc = v => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const fmtDelta = d => {
  if (d === null || d === undefined) return '<span style="color:#888">—</span>';
  if (d > 0) return `<span style="color:#1a7f37">▲ +${d}</span>`;
  if (d < 0) return `<span style="color:#cf222e">▼ ${d}</span>`;
  return '<span style="color:#888">0</span>';
};
const th = 'style="border:1px solid #d0d7de;padding:6px 10px;background:#f6f8fa;text-align:left"';
const td = 'style="border:1px solid #d0d7de;padding:6px 10px"';
const table = (head, rows) =>
  `<table style="border-collapse:collapse;font-family:Arial,sans-serif;font-size:14px;margin:8px 0 18px">` +
  `<tr>${head.map(h => `<th ${th}>${h}</th>`).join('')}</tr>` +
  rows.map(r => `<tr>${r.map(c => `<td ${td}>${c}</td>`).join('')}</tr>`).join('') + `</table>`;

const LABELS = {
  issues_opened: 'Issues открыто', issues_closed: 'Issues закрыто',
  prs_opened: 'PR открыто', prs_merged: 'PR смёржено',
};
const d = s.delta;
const prevLabel = s.prev ? `${s.prev.week_start} — ${s.prev.week_end}` : 'нет данных';

const totalsRows = Object.keys(LABELS).map(k => [
  LABELS[k], `<b>${s.totals[k]}</b>`, s.prev ? s.prev.totals[k] : '—', fmtDelta(d ? d.totals[k] : null),
]);
const typeRows = Object.keys(s.by_type).map(t => [
  esc(t), s.by_type[t].opened, fmtDelta(d ? d.by_type[t].opened : null),
  s.by_type[t].closed, fmtDelta(d ? d.by_type[t].closed : null),
]);
const authors = Object.entries(s.by_author).sort((a, b) =>
  (b[1].issues_opened + b[1].prs_opened) - (a[1].issues_opened + a[1].prs_opened));
const authorRows = authors.length
  ? authors.map(([login, a]) => [esc(login), a.issues_opened, a.issues_closed, a.prs_opened, a.prs_merged])
  : [['—', 0, 0, 0, 0]];
const issueRows = (s.issues || []).map(i => [
  `<a href="${esc(i.url)}">#${i.number}</a>`, esc(i.title), esc(i.type), esc(i.author),
]);

const aiHtml = esc(ai || 'AI-комментарий не сгенерирован.').replace(/\n/g, '<br>');

const html = `<div style="font-family:Arial,sans-serif;color:#1f2328;max-width:760px">
<h2 style="margin:0 0 4px">📊 Еженедельная статистика ${esc(s.repo)}</h2>
<div style="color:#57606a;margin-bottom:16px">Неделя: <b>${s.week_start} — ${s.week_end}</b> · сравнение с неделей ${esc(prevLabel)}</div>

<h3 style="margin:0">Итоги недели</h3>
${table(['Метрика', 'Эта неделя', 'Прошлая неделя', 'Δ'], totalsRows)}

<h3 style="margin:0">По типу Issues</h3>
${table(['Тип', 'Открыто', 'Δ открыто', 'Закрыто', 'Δ закрыто'], typeRows)}

<h3 style="margin:0">По автору</h3>
${table(['Автор', 'Issues открыл', 'Issues закрыто', 'PR открыл', 'PR смёржено'], authorRows)}

${issueRows.length ? `<h3 style="margin:0">Issues, открытые за неделю</h3>${table(['#', 'Заголовок', 'Тип', 'Автор'], issueRows)}` : ''}

<div style="border-left:4px solid #8250df;background:#fbefff;padding:12px 16px;margin:8px 0 16px">
  <div style="font-weight:bold;margin-bottom:6px">🤖 AI-комментарий недели</div>
  <div>${aiHtml}</div>
</div>
<div style="color:#8c959f;font-size:12px">Сгенерировано n8n · данные: GitHub Search API · история: Data Table weekly_issue_stats</div>
</div>`;

return [{ json: {
  subject: `Статистика Issues ${s.repo}: ${s.week_start} — ${s.week_end}`,
  html,
}}];
